       61:       size_t rowbytes = png_get_rowbytes(png_ptr, info_ptr);
       62: 
       63:       /* Failure to initialize these is harmless */
       64:       row = malloc(rowbytes);
       65:       display = malloc(rowbytes);
       66: 
